using namespace std;

class Solution {
    bool backtrack(vector<int>& counts, vector<int>& quantity, int q_idx) {
        if (q_idx == (int)quantity.size()) return true;
        int req = quantity[q_idx];
        for (size_t i = 0; i < counts.size(); ++i) {
            if (counts[i] >= req) {
                counts[i] -= req;
                if (backtrack(counts, quantity, q_idx + 1)) return true;
                counts[i] += req;
            }
            if (counts[i] == 0) break;
        }
        return false;
    }
public:
    bool canDistribute(vector<int>& nums, vector<int>& quantity) {
        unordered_map<int, int> freq;
        for (int x : nums) freq[x]++;
        vector<int> counts;
        for (auto& [k, v] : freq) counts.push_back(v);
        sort(counts.rbegin(), counts.rend());
        if (counts.size() > 50) counts.resize(50);
        sort(quantity.rbegin(), quantity.rend());
        return backtrack(counts, quantity, 0);
    }
};

import java.util.*;

class Solution {
    private boolean backtrack(int[] counts, int[] quantity, int qIdx) {
        if (qIdx == quantity.length) return true;
        int req = quantity[qIdx];
        for (int i = 0; i < counts.length; ++i) {
            if (counts[i] >= req) {
                counts[i] -= req;
                if (backtrack(counts, quantity, qIdx + 1)) return true;
                counts[i] += req;
            }
            if (counts[i] == 0) break;
        }
        return false;
    }

    public boolean canDistribute(int[] nums, int[] quantity) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : nums) freq.put(x, freq.getOrDefault(x, 0) + 1);
        List<Integer> list = new ArrayList<>(freq.values());
        list.sort(Collections.reverseOrder());
        int m = Math.min(list.size(), 50);
        int[] counts = new int[m];
        for (int i = 0; i < m; ++i) counts[i] = list.get(i);
        Arrays.sort(quantity);
        int[] q = new int[quantity.length];
        for (int i = 0; i < quantity.length; ++i) q[i] = quantity[quantity.length - 1 - i];
        return backtrack(counts, q, 0);
    }
}

