var canDistribute = function(nums, quantity) {
    const freq = new Map();
    for (const x of nums) {
        freq.set(x, (freq.get(x) || 0) + 1);
    }
    const counts = Array.from(freq.values()).sort((a, b) => b - a).slice(0, 50);
    quantity.sort((a, b) => b - a);

    function backtrack(qIdx) {
        if (qIdx === quantity.length) return true;
        const req = quantity[qIdx];
        for (let i = 0; i < counts.length; ++i) {
            if (counts[i] >= req) {
                counts[i] -= req;
                if (backtrack(qIdx + 1)) return true;
                counts[i] += req;
            }
            if (counts[i] === 0) break;
        }
        return false;
    }

    return backtrack(0);
};
